{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative care for whole-person wellness</title>
  <meta name="description" content="A playful, premium approach to holistic health in {{CITY}}, {{STATE}} — education-first, personalized plans, and compassionate follow-ups." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-zen">
  <header class="site-header">
    <div class="container header-grid">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" id="mainNav">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Concerns</a>
        <a href="/approach.html">My Way</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">Meet</a>
        <a href="/book.html" class="cta small">Book</a>
        <button class="nav-toggle" id="navToggle" aria-label="Menu">☰</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="container hero-inner">
        <div class="hero-copy">
          <h1 class="eyebrow">Nurture the whole you</h1>
          <h2>{{BUSINESS_NAME}} — {{TAGLINE}}</h2>
          <p class="lead">Playful, premium integrative care that centers education, evidence-informed options, and your lived experience. We partner to support sleep, digestion, stress resilience, and sustained energy.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
          </div>
        </div>
        <div class="hero-card">
          <div class="card-top">
            <div class="avatar" aria-hidden="true">{{PRACTITIONER_NAME}}</div>
            <div class="pract-info">
              <strong>{{PRACTITIONER_NAME}}, {{CREDENTIALS}}</strong>
              <span class="muted">Integrative & whole-person medicine in {{CITY}}, {{STATE}}</span>
            </div>
          </div>
          <p class="tiny">Care is education-forward. No miracle promises — just practical plans, proven strategies, and attentive follow-ups.</p>
          <dl class="quick-list">
            <div>
              <dt>Initial visit</dt>
              <dd>90 minutes</dd>
            </div>
            <div>
              <dt>Personalized plan</dt>
              <dd>Herbal, nutritional, and lifestyle options</dd>
            </div>
            <div>
              <dt>Labs (optional)</dt>
              <dd>Discussed as educational tools</dd>
            </div>
          </dl>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof container" id="social-proof">
      <h3>Kind words from people who felt seen</h3>
      <div class="testimonials">
        <blockquote>
          "I finally understood why I couldn't sleep. The plan was practical and felt tailor-made." <cite>— A. in {{CITY}}</cite>
        </blockquote>
        <blockquote>
          "Gentle, smart, and a true partner in my health—no pressure, just options." <cite>— J. *</cite>
        </blockquote>
      </div>
      <p class="muted small">*Testimonials are individual experiences. Results vary and are not guaranteed.</p>
    </section>

    <!-- BENEFITS -->
    <section class="benefits" id="benefits">
      <div class="container">
        <h3>How this approach helps</h3>
        <ul class="benefit-grid">
          <li>
            <h4>Whole-person focus</h4>
            <p>We look at sleep, digestion, stress, environment, and mindset — not just one lab value.</p>
          </li>
          <li>
            <h4>Evidence + experience</h4>
            <p>Educational conversations about what's known, safe, and appropriate for you.</p>
          </li>
          <li>
            <h4>Practical tools</h4>
            <p>Actionable steps you can actually fit into your life — and refine over time.</p>
          </li>
          <li>
            <h4>Compassionate follow-up</h4>
            <p>Check-ins to adjust plans and celebrate small wins.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process container" id="process">
      <h3>How we work — simple, transparent</h3>
      <ol class="steps">
        <li>
          <h4>1. Intake & listening</h4>
          <p>We begin with a deep-history intake — symptoms, priorities, lifestyle, and what you've tried. This is education-first exploration.</p>
        </li>
        <li>
          <h4>2. Personalized plan</h4>
          <p>Nutrition, movement, sleep support, mindful practices, and selective complementary options aligned with your goals.</p>
        </li>
        <li>
          <h4>3. Optional labs (educational)</h4>
          <p>If labs can clarify a question, we discuss what might be helpful and what to expect. Labs are tools, not directives.</p>
        </li>
        <li>
          <h4>4. Follow-ups & refinements</h4>
          <p>Short check-ins help us tweak the plan, celebrate gains, and address obstacles.</p>
        </li>
      </ol>
    </section>

    <!-- FAQ -->
    <section class="faq container" id="faq">
      <h3>Questions people often ask</h3>
      <div class="qa">
        <details>
          <summary>Do you promise cures?</summary>
          <p>No. We focus on education and practical support. Treatments aim to improve quality of life and function; outcomes vary.</p>
        </details>
        <details>
          <summary>Are labs required?</summary>
          <p>Not always. Labs are offered when they help clarify treatment direction. We'll explain rationale and limits.</p>
        </details>
        <details>
          <summary>What conditions do you commonly see?</summary>
          <p>Stress, sleep difficulties, digestive concerns, chronic low energy, and low-grade inflammation are frequent. See our "Concerns" page for more; individualized evaluation is essential.</p>
        </details>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet" id="lead-magnet">
      <div class="container magnet-inner">
        <div class="magnet-copy">
          <h3>Free guide: 5 small habits to boost steady energy</h3>
          <p>Download a concise, evidence-friendly checklist with practical steps you can try this week. No spam — just helpful notes.</p>
          <form id="magnetForm" class="magnet-form">
            <label for="name">Your name</label>
            <input type="text" id="name" name="name" placeholder="Your name" required>
            <label for="email">Email</label>
            <input type="email" id="email" name="email" placeholder="you@example.com" required>
            <button class="btn primary" type="submit">Get the guide</button>
            <p class="muted tiny">We respect your privacy. This guide is educational and not medical advice.</p>
          </form>
        </div>
        <div class="magnet-card">
          <svg class="icon-ebook" viewBox="0 0 64 64" aria-hidden="true">
            <rect x="6" y="8" width="40" height="48" rx="3" fill="url(#g)" />
            <rect x="50" y="12" width="8" height="40" rx="2" fill="#fff" opacity="0.06" />
            <defs>
              <linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#ffd6a5"/><stop offset="1" stop-color="#cde7ff"/></linearGradient>
            </defs>
          </svg>
          <p class="tiny">Instant PDF sent to your inbox. Educational material to help you start exploring low-cost, safe strategies.</p>
        </div>
      </div>
    </section>

    <!-- CTA BANNER -->
    <section class="cta-banner" id="cta">
      <div class="container">
        <h3>Ready to try an integrative visit?</h3>
        <p>Begin with a thoughtful intake that centers your goals. We’ll make an approachable plan together.</p>
        <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Integrative medicine & holistic coaching in {{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <a href="tel:{{PHONE}}">Call: {{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">Email: {{EMAIL}}</a>
      </div>
      <div class="muted small">© {{BUSINESS_NAME}} — No guaranteed cures. Educational care only.</div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
