{"path":"assets/css/styles.css","content":"/* Zen Minimal — playful premium stylesheet */
:root{
  --bg:#fbfbfc; --accent-1:#6b8cff; --accent-2:#ffb86b; --muted:#6b7280; --card:#ffffff; --radius:12px; --max:1100px; --gap:24px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; background:linear-gradient(180deg,#fbfbff 0%, #ffffff 100%); color:#0b1220; -webkit-font-smoothing:antialiased}
.container{max-width:var(--max);margin:0 auto;padding:40px 20px}
.header-grid{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
.brand{font-weight:700;color:var(--accent-1);text-decoration:none;font-size:1.1rem}
.main-nav{display:flex;gap:16px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.main-nav a.cta{background:var(--accent-1);color:#fff;padding:8px 12px}
.nav-toggle{display:none;background:none;border:0;font-size:1.1rem}

.hero{padding:80px 0;background-repeat:no-repeat;background-size:cover;border-bottom:1px solid rgba(11,18,32,0.04)}
.hero-inner{display:grid;grid-template-columns:1fr 360px;gap:40px;align-items:start}
.eyebrow{font-size:0.95rem;color:var(--accent-2);margin:0}
.hero h2{font-size:2.2rem;margin:8px 0 16px}
.lead{color:var(--muted);margin:0 0 20px}
.hero-cta .btn{margin-right:12px}
.btn{display:inline-block;background:var(--card);border:1px solid rgba(11,18,32,0.06);padding:10px 16px;border-radius:10px;text-decoration:none;color:inherit}
.btn.primary{background:linear-gradient(90deg,var(--accent-1),#8ad1ff);color:#fff;border:0;box-shadow:0 6px 18px rgba(107,140,255,0.18)}
.btn.ghost{background:transparent;border:1px solid rgba(11,18,32,0.06)}
.btn.large{padding:14px 22px;font-weight:600}
.card-top{display:flex;gap:12px;align-items:center;margin-bottom:10px}
.avatar{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,var(--accent-2),#ffd6a5);display:flex;align-items:center;justify-content:center;font-weight:700;color:#3a2b20}
.pract-info strong{display:block}
.muted{color:var(--muted)}
.small{font-size:0.9rem}
.tiny{font-size:0.85rem}
.quick-list{display:grid;grid-template-columns:repeat(1,1fr);gap:8px;margin:10px 0 0}
.quick-list dt{font-weight:600}

.social-proof{padding:40px 0;text-align:center}
.testimonials{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}
blockquote{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(11,18,32,0.04);margin:0}

.benefits{padding:40px 0}
.benefit-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;list-style:none;padding:0;margin:16px 0 0}
.benefit-grid li{background:var(--card);padding:18px;border-radius:12px}

.process{padding:30px 0}
.steps{list-style:decimal;margin:12px 0 0 18px;padding:0}
.steps li{margin-bottom:14px}

.faq{padding:30px 0}
.qa details{background:var(--card);padding:12px;border-radius:10px;margin-bottom:10px}
.qa summary{cursor:pointer;font-weight:600}

.lead-magnet{padding:40px 0;border-top:1px solid rgba(11,18,32,0.03);border-bottom:1px solid rgba(11,18,32,0.03)}
.magnet-inner{display:grid;grid-template-columns:1fr 260px;gap:24px;align-items:center}
.magnet-form{display:flex;flex-direction:column;gap:8px}
.magnet-form input{padding:10px;border-radius:8px;border:1px solid rgba(11,18,32,0.06)}
.magnet-card{background:linear-gradient(180deg,#fff,#fcf9f4);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(11,18,32,0.04)}
.icon-ebook{width:64px;height:64px;display:block;margin-bottom:8px}

.cta-banner{padding:30px 0;text-align:center}

.site-footer{padding:24px 0;background:transparent;border-top:1px solid rgba(11,18,32,0.03)}
.footer-grid{display:flex;gap:12px;align-items:center;justify-content:space-between}
.footer-grid a{color:var(--muted);text-decoration:none}

@media (max-width:880px){
  .hero-inner{grid-template-columns:1fr;}
  .magnet-inner{grid-template-columns:1fr}
  .testimonials{grid-template-columns:1fr}
  .benefit-grid{grid-template-columns:1fr}
  .nav-toggle{display:inline-block}
  .main-nav{position:fixed;top:64px;right:12px;background:rgba(255,255,255,0.98);padding:12px;border-radius:12px;box-shadow:0 10px 30px rgba(11,18,32,0.06);display:none;flex-direction:column}
  .main-nav.open{display:flex}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var toggle = document.getElementById('navToggle');
  var nav = document.getElementById('mainNav');
  if(toggle && nav){
    toggle.addEventListener('click', function(){
      nav.classList.toggle('open');
      var expanded = nav.classList.contains('open');
      toggle.setAttribute('aria-expanded', expanded);
    });
  }

  // Smooth scroll for anchor links
  document.addEventListener('click', function(e){
    var t = e.target;
    if(t.tagName === 'A' && t.getAttribute('href') && t.getAttribute('href').startsWith('#')){
      var id = t.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth',block:'start'}); }
    }
  });

  // Lead magnet form: emulate download + basic validation
  var form = document.getElementById('magnetForm');
  if(form){
    form.addEventListener('submit', function(ev){
      ev.preventDefault();
      var name = document.getElementById('name').value.trim();
      var email = document.getElementById('email').value.trim();
      if(!email){ alert('Please provide an email to receive the guide.'); return; }
      // Minimal email regex
      if(!/\S+@\S+\.\S+/.test(email)){ alert('Please provide a valid email.'); return; }
      // faux submit: show friendly confirmation
      form.querySelector('button').textContent = 'Sending…';
      setTimeout(function(){
        form.innerHTML = '<p class="tiny">Thanks, '+(name?name:'friend')+" — your guide is on its way. Check your inbox for an email from {{BUSINESS_NAME}}.</p>";
      },800);
    });
  }

})();
"} 
